import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;import java.util.Stack;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int t = Integer.parseInt(br.readLine().trim());StringBuilder sb = new StringBuilder();while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());long[] a = new long[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Long.parseLong(st.nextToken());}int[] left = new int[n];int[] right = new int[n];Stack<Integer> stack = new Stack<Integer>();for (int i = 0; i < n; i++) {while (!stack.isEmpty() && a[stack.peek()] >= a[i]) {stack.pop();}left[i] = stack.isEmpty() ? -1 : stack.peek();stack.push(i);}stack.clear();for (int i = n - 1; i >= 0; i--) {while (!stack.isEmpty() && a[stack.peek()] >= a[i]) {stack.pop();}right[i] = stack.isEmpty() ? -1 : stack.peek();stack.push(i);}for (int i = 0; i < n; i++) {if (i == 0 || i == n - 1 || left[i] == -1 || right[i] == -1) {sb.append("-1");} else {int ops = (i - left[i] - 1) + (right[i] - i - 1);sb.append(ops);}if (i < n - 1) sb.append(" ");}sb.append("\n");}System.out.print(sb.toString());}}